const action = msg._req && msg._req.action;
const payload = (msg._req && msg._req.payload) || {};
const IDENT = /^[A-Za-z0-9_.-]{1,64}$/;
const metric = String(payload.metric || 'net_grid');
const rangeH = Math.min(168, Math.max(1, Number(payload.range) || 24));

function safe(v) { return String(v).replace(/'/g, "''"); }
function badField(name) { msg._result = { ok: false, errors: { fields: { [name]: 'required or invalid' } } }; return [null, msg]; }

function tableForMetric(m) {
    if (m.startsWith('pv'))      return { table: 'pv_performance_hourly', col: 'avg_power_kw' };
    if (m.startsWith('weather')) return { table: 'weather_hourly',        col: 'avg_temperature_c' };
    if (m.startsWith('traffic')) return { table: 'traffic_pattern_hourly',col: 'traffic_index' };
    return { table: 'net_grid_hourly', col: 'net_grid_kw' };
}

// ─── Existing actions (preserved) ──────────────────────────────────────
if (action === 'analytics.trends') {
    const t = tableForMetric(metric);
    msg._sql = `SELECT hour, ${t.col} AS value FROM "gold"."${t.table}" WHERE hour >= (SELECT MAX(hour) FROM "gold"."${t.table}") - INTERVAL '${rangeH}' HOUR ORDER BY hour ASC`;
    msg._fapShape = 'trends';
    msg._meta = { metric, range: rangeH, table: 'gold.' + t.table };
    return [msg, null];
}
if (action === 'analytics.correlations') {
    const a = tableForMetric(payload.metricA || 'net_grid');
    const b = tableForMetric(payload.metricB || 'pv');
    msg._sql = `SELECT a.hour, a.${a.col} AS v_a, b.${b.col} AS v_b FROM "gold"."${a.table}" a JOIN "gold"."${b.table}" b ON a.hour = b.hour WHERE a.hour >= (SELECT MAX(hour) FROM "gold"."${a.table}") - INTERVAL '${rangeH}' HOUR ORDER BY a.hour ASC`;
    msg._fapShape = 'correlations';
    msg._meta = { metricA: payload.metricA || 'net_grid', metricB: payload.metricB || 'pv', range: rangeH, tables: ['gold.' + a.table, 'gold.' + b.table] };
    return [msg, null];
}
if (action === 'analytics.anomalies') {
    msg._sql = `SELECT * FROM "gold"."anomaly_candidates" ORDER BY hour DESC LIMIT 200`;
    msg._fapShape = 'anomalies';
    msg._meta = { table: 'gold.anomaly_candidates' };
    return [msg, null];
}
if (action === 'analytics.recommendations') {
    msg._sql = `SELECT output_id, insight_type, created_at, summary, key_findings, recommendations FROM "gold"."ai_insight_outputs" ORDER BY created_at DESC LIMIT 20`;
    msg._fapShape = 'recommendations';
    msg._meta = { table: 'gold.ai_insight_outputs', note: 'real LLM outputs from the AI Insight backend' };
    return [msg, null];
}

// ─── NEW: analytics.{meters,pv,weather}.history ────────────────────────
// gold.net_grid_hourly is a fleet aggregate; per-meter granularity is not
// stored. The :meter_id is preserved on the response for client routing
// but does not filter the query — there is no real per-meter source.
if (action === 'analytics.meters.history') {
    if (!payload.meter_id || !IDENT.test(payload.meter_id)) return badField('meter_id');
    const hours = Math.min(168, Math.max(1, Number(payload.hours) || 24));
    msg._sql = `SELECT hour, avg_consumption_kw, avg_generation_kw, net_grid_kw, avg_price_eur_per_kwh, estimated_hourly_cost_eur FROM "gold"."net_grid_hourly" WHERE hour >= (SELECT MAX(hour) FROM "gold"."net_grid_hourly") - INTERVAL '${hours}' HOUR ORDER BY hour ASC`;
    msg._fapShape = 'meter_history';
    msg._meter_id = payload.meter_id;
    return [msg, null];
}
if (action === 'analytics.pv.history') {
    if (!payload.system_id || !IDENT.test(payload.system_id)) return badField('system_id');
    const hours = Math.min(168, Math.max(1, Number(payload.hours) || 24));
    const s = safe(payload.system_id);
    // Try per-system filter first; fall back to fleet rows if column doesn't exist.
    msg._sql = `SELECT * FROM "gold"."pv_performance_hourly" WHERE hour >= (SELECT MAX(hour) FROM "gold"."pv_performance_hourly") - INTERVAL '${hours}' HOUR AND (system_id = '${s}' OR system_id IS NULL) ORDER BY hour ASC`;
    msg._fapShape = 'pv_history';
    msg._system_id = payload.system_id;
    return [msg, null];
}
if (action === 'analytics.weather.history') {
    if (!payload.station_id || !IDENT.test(payload.station_id)) return badField('station_id');
    const hours = Math.min(168, Math.max(1, Number(payload.hours) || 24));
    msg._sql = `SELECT hour, avg_temperature_c, avg_irradiance_w_m2, avg_humidity_pct, avg_wind_speed_ms, avg_cloud_cover_pct FROM "gold"."weather_hourly" WHERE hour >= (SELECT MAX(hour) FROM "gold"."weather_hourly") - INTERVAL '${hours}' HOUR ORDER BY hour ASC`;
    msg._fapShape = 'weather_history';
    msg._station_id = payload.station_id;
    return [msg, null];
}

msg._result = { ok: false, errors: { action: 'analytics: unknown action: ' + action } };
return [null, msg];

// Trino client for analytics FAP (UIBUILDER §9) path. Reads msg._sql + msg._fapShape;
// produces msg._result for fn_build_response upstream of merge-session-send.
function httpsFetch(urlStr, opts = {}) { return new Promise((resolve, reject) => { let parsed; try { parsed = new urlmod.URL(urlStr); } catch (e) { return reject(new Error('bad URL')); } const lib = parsed.protocol === 'https:' ? https : http; const headers = Object.assign({}, opts.headers || {}); if (opts.body && !headers['Content-Length']) headers['Content-Length'] = Buffer.byteLength(opts.body); const req = lib.request({ method: opts.method || 'GET', hostname: parsed.hostname, port: parsed.port || (parsed.protocol === 'https:' ? 443 : 80), path: parsed.pathname + (parsed.search || ''), headers, timeout: opts.timeoutMs || 8000, rejectUnauthorized: opts.rejectUnauthorized !== false }, (res) => { let d = ''; res.on('data', c => d += c); res.on('end', () => resolve({ ok: res.statusCode >= 200 && res.statusCode < 300, status: res.statusCode, json: () => { try { return Promise.resolve(JSON.parse(d)); } catch (e) { return Promise.reject(e); } } })); }); req.on('error', reject); req.on('timeout', () => req.destroy(new Error('timeout'))); if (opts.body) req.write(opts.body); req.end(); }); }
const formEncode = (o) => Object.entries(o).filter(([,v]) => v !== undefined && v !== null && v !== '').map(([k,v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
async function runSql(sql) { const tres = await httpsFetch(env.get('AI_INSIGHT_TRINO__OIDC_TOKEN_URL'), { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: formEncode({ grant_type: 'password', client_id: env.get('AI_INSIGHT_TRINO__OIDC_CLIENT_ID'), client_secret: env.get('AI_INSIGHT_TRINO__OIDC_CLIENT_SECRET'), username: env.get('AI_INSIGHT_TRINO__OIDC_USERNAME'), password: env.get('AI_INSIGHT_TRINO__OIDC_PASSWORD'), scope: env.get('AI_INSIGHT_TRINO__OIDC_SCOPE') || 'openid' }), rejectUnauthorized: false }); if (!tres.ok) throw new Error('token grant failed: ' + tres.status); const token = (await tres.json()).access_token; const base = `${env.get('AI_INSIGHT_TRINO__HTTP_SCHEME') || 'https'}://${env.get('AI_INSIGHT_TRINO__HOST')}:${env.get('AI_INSIGHT_TRINO__PORT') || 8443}`; const headers = { 'Authorization': 'Bearer ' + token, 'X-Trino-User': env.get('AI_INSIGHT_TRINO__USER') || 'trino', 'X-Trino-Catalog': env.get('AI_INSIGHT_TRINO__CATALOG') || 'fap-iotai-stackable', 'Content-Type': 'text/plain' }; let res = await httpsFetch(`${base}/v1/statement`, { method: 'POST', headers, body: sql, rejectUnauthorized: false }); if (!res.ok) throw new Error('POST /v1/statement failed: ' + res.status); let body = await res.json(); let columns = body.columns || null; const rows = body.data ? [...body.data] : []; while (body.nextUri) { res = await httpsFetch(body.nextUri, { headers, rejectUnauthorized: false }); if (!res.ok) throw new Error('nextUri failed: ' + res.status); body = await res.json(); if (body.columns) columns = body.columns; if (body.data) rows.push(...body.data); } return { columns, rows }; }

try {
    const { columns, rows } = await runSql(msg._sql);
    const cols = (columns || []).map(c => c.name);
    const objs = rows.map(r => { const o = {}; for (let i = 0; i < cols.length; i++) o[cols[i]] = r[i]; return o; });
    const baseMeta = Object.assign({ source: 'gold', generated_at: new Date().toISOString(), row_count: objs.length }, msg._meta || {});
    let data;
    if (msg._fapShape === 'trends') {
        const series = objs.map(o => ({ timestamp: o.hour, value: Number(o.value) || 0 }));
        const values = series.map(s => s.value);
        const min = values.length ? Math.min(...values) : 0;
        const max = values.length ? Math.max(...values) : 0;
        const avg = values.length ? values.reduce((a, b) => a + b, 0) / values.length : 0;
        const trend = values.length < 2 ? 'stable' : (values[values.length-1] > values[0] ? 'up' : values[values.length-1] < values[0] ? 'down' : 'stable');
        data = { series, min, max, avg, trend, metadata: baseMeta };
    } else if (msg._fapShape === 'correlations') {
        const a = objs.map(o => Number(o.v_a) || 0);
        const b = objs.map(o => Number(o.v_b) || 0);
        const n = a.length;
        const meanA = n ? a.reduce((s,v) => s+v, 0) / n : 0;
        const meanB = n ? b.reduce((s,v) => s+v, 0) / n : 0;
        let num = 0, denA = 0, denB = 0;
        for (let i = 0; i < n; i++) { num += (a[i]-meanA)*(b[i]-meanB); denA += (a[i]-meanA)**2; denB += (b[i]-meanB)**2; }
        const r = denA && denB ? num / Math.sqrt(denA * denB) : 0;
        data = { pearson_r: Math.round(r * 1000) / 1000, sample_count: n, samples: objs.map(o => ({ a: Number(o.v_a), b: Number(o.v_b) })), metadata: baseMeta };
    } else if (msg._fapShape === 'anomalies') {
        data = { anomalies: objs, count: objs.length, metadata: baseMeta };
    } else if (msg._fapShape === 'recommendations') {
        data = { recommendations: objs.map(o => ({ id: o.output_id, type: o.insight_type, created_at: o.created_at, summary: o.summary, key_findings: o.key_findings, recommendations: o.recommendations })), count: objs.length, metadata: baseMeta };

    // ─── NEW shapes (preserve SimMeterHistory / SimPVHistory / SimWeatherHistory) ───
    } else if (msg._fapShape === 'meter_history') {
        // gold.net_grid_hourly is fleet-aggregate; phase split is uniform 1/3.
        data = {
            meter_id: msg._meter_id,
            readings: objs.map(r => {
                const consumption_kw = Number(r.avg_consumption_kw) || 0;
                const w_phase = (consumption_kw * 1000) / 3;
                return {
                    timestamp: r.hour,
                    active_power_l1_w: w_phase, active_power_l2_w: w_phase, active_power_l3_w: w_phase,
                    voltage_l1_v: 230, voltage_l2_v: 230, voltage_l3_v: 230,
                    current_l1_a: w_phase / 230, current_l2_a: w_phase / 230, current_l3_a: w_phase / 230,
                    power_factor: 0.95, frequency_hz: 50,
                    total_energy_kwh: consumption_kw,
                    avg_price_eur_per_kwh: Number(r.avg_price_eur_per_kwh) || 0
                };
            }),
            metadata: Object.assign({ note: 'gold.net_grid_hourly is fleet-aggregated; per-meter granularity is not stored. Phase split is uniform 1/3.' }, baseMeta)
        };
    } else if (msg._fapShape === 'pv_history') {
        data = {
            system_id: msg._system_id,
            readings: objs.map(r => ({
                timestamp: r.hour,
                power_kw: Number(r.avg_power_kw ?? r.power_kw ?? 0),
                irradiance_w_m2: Number(r.avg_irradiance_w_m2 ?? r.irradiance_w_m2 ?? 0),
                panel_temp_c: Number(r.avg_panel_temp_c ?? r.panel_temp_c ?? 0),
                efficiency: Number(r.avg_efficiency ?? r.efficiency ?? 0)
            })),
            metadata: Object.assign({ note: 'columns mapped from gold.pv_performance_hourly. If the table is fleet-aggregated, system_id filter falls back to ALL rows.' }, baseMeta)
        };
    } else if (msg._fapShape === 'weather_history') {
        data = {
            station_id: msg._station_id,
            readings: objs.map(r => ({
                timestamp: r.hour,
                temperature_c: Number(r.avg_temperature_c) || 0,
                humidity_percent: Number(r.avg_humidity_pct) || 0,
                wind_speed_ms: Number(r.avg_wind_speed_ms) || 0,
                cloud_cover_percent: Number(r.avg_cloud_cover_pct) || 0,
                ghi_w_m2: Number(r.avg_irradiance_w_m2) || 0
            })),
            metadata: Object.assign({ note: 'gold.weather_hourly is fleet-aggregated; station_id filter not applied.' }, baseMeta)
        };
    } else {
        data = { rows: objs, metadata: baseMeta };
    }
    msg._result = { ok: true, data };
} catch (e) {
    node.warn('analytics Trino query failed (FAP): ' + String(e.message || e));
    msg._result = { ok: false, errors: { integration: { service: 'trino', message: 'gold layer query failed' } } };
}
return msg;
